with d as (select value r from jsonb_array_elements($q$[{"slug":"toast-skagen","title":"Toast Skagen","cuisine":"scandinavian","meal_types":["lunch","snack"],"diets":["pescatarian"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"toast-skagen","title":"Toast Skagen","summary":"Sweden's classic prawn toast: cold prawns in a dill and lemon dressing, piled on butter-fried bread.","cuisine":"scandinavian","diets":["pescatarian"],"mealTypes":["lunch","snack"],"difficulty":"easy","prepMinutes":20,"cookMinutes":5,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Prawns","items":[{"item":"cooked prawns","raw":"400g cooked prawns, peeled and roughly chopped","quantity":400,"unit":"g","ingredientId":"cooked-prawn","prep":"peeled and roughly chopped"},{"item":"mayonnaise","raw":"3 tbsp mayonnaise","quantity":3,"unit":"tbsp","ingredientId":"mayonnaise"},{"item":"crème fraîche","raw":"3 tbsp crème fraîche","quantity":3,"unit":"tbsp","ingredientId":"creme-fraiche"},{"item":"Dijon mustard","raw":"1 tsp Dijon mustard","quantity":1,"unit":"tsp","ingredientId":"dijon-mustard"},{"item":"dill","raw":"2 tbsp dill, finely chopped","quantity":2,"unit":"tbsp","ingredientId":"dill","prep":"finely chopped"},{"item":"chives","raw":"1 tbsp chives, finely chopped","quantity":1,"unit":"tbsp","ingredientId":"chives","prep":"finely chopped"},{"item":"lemon juice","raw":"1 tbsp lemon juice","quantity":1,"unit":"tbsp","ingredientId":"lemon"},{"item":"white pepper","raw":"Pinch of white pepper","quantity":1,"unit":"pinch","ingredientId":"white-pepper"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"}]},{"title":"Toast","items":[{"item":"white sandwich bread","raw":"4 slices white sandwich bread","quantity":4,"unit":"slice","ingredientId":"white-bread"},{"item":"butter","raw":"30g butter","quantity":30,"unit":"g","ingredientId":"butter"},{"item":"lemon","raw":"1 lemon, cut into wedges","quantity":1,"ingredientId":"lemon","prep":"cut into wedges"},{"item":"dill","raw":"4 dill sprigs","quantity":4,"unit":"sprig","ingredientId":"dill"}]}],"steps":[{"text":"Mix the mayonnaise, crème fraîche, mustard, dill, chives and lemon juice. Fold in the prawns and season with white pepper and salt. Keep in the fridge until needed."},{"text":"Cut the crusts off the bread and halve each slice diagonally. Melt the butter in a frying pan over medium heat and fry the bread for 1 to 2 minutes a side until golden."},{"text":"Pile the prawn mixture onto the warm, crisp toast and top each with a dill sprig. Serve straight away with lemon wedges."}],"notes":["Keep the prawns cold until the last minute, and don't leave the finished toasts out for more than 2 hours.","A spoonful of salmon roe on top is the traditional finish."],"source":"user","provenance":"ai-draft"}},{"slug":"janssons-temptation","title":"Jansson's Temptation","cuisine":"scandinavian","meal_types":["dinner"],"diets":["pescatarian"],"difficulty":"easy","total_minutes":80,"recipe":{"id":"janssons-temptation","title":"Jansson's Temptation","summary":"A Swedish gratin of potato matchsticks, sweet onion and anchovies baked in cream until golden.","cuisine":"scandinavian","diets":["pescatarian"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":20,"cookMinutes":60,"servings":4,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Gratin","items":[{"item":"butter","raw":"40g butter","quantity":40,"unit":"g","ingredientId":"butter"},{"item":"brown onions","raw":"2 brown onions, thinly sliced","quantity":2,"ingredientId":"brown-onion","prep":"thinly sliced"},{"item":"floury potatoes","raw":"1kg floury potatoes, peeled and cut into thin matchsticks","quantity":1,"unit":"kg","ingredientId":"potato","prep":"peeled and cut into thin matchsticks"},{"item":"anchovy fillets","raw":"60g anchovy fillets, drained and chopped, oil kept","quantity":60,"unit":"g","ingredientId":"anchovy","prep":"drained and chopped, oil kept"},{"item":"thickened cream","raw":"300ml thickened cream","quantity":300,"unit":"ml","ingredientId":"cream"},{"item":"milk","raw":"100ml milk","quantity":100,"unit":"ml","ingredientId":"milk"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"},{"item":"dried breadcrumbs","raw":"2 tbsp dried breadcrumbs","quantity":2,"unit":"tbsp","ingredientId":"breadcrumbs"}]},{"title":"To serve","items":[{"item":"Green salad","raw":"Green salad, to serve","ingredientId":"salad-leaves","prep":"to serve"}]}],"steps":[{"text":"Heat the oven to 200°C (180°C fan-forced) and butter a 2L baking dish with a little of the butter."},{"text":"Melt half the remaining butter in a frying pan over medium heat and cook the onions for 10 minutes until soft and pale gold."},{"text":"Spread a third of the potatoes in the dish, then half the onions and half the anchovies. Repeat, finishing with a layer of potato. Season with the pepper; the anchovies bring enough salt."},{"text":"Warm the cream, milk and 1 tbsp of the anchovy oil and pour it over. Scatter with the breadcrumbs and dot with the rest of the butter."},{"text":"Bake for 50 to 60 minutes, until the top is golden, the cream has thickened and a knife slides easily through the potatoes. Rest for 10 minutes and serve with a green salad."}],"notes":["Swedish 'ansjovis' are sprats in a sweet spiced brine, sold at IKEA food markets. If you find them, use a 125g tin and its brine instead of the anchovies.","It's a Christmas table classic in Sweden, and good alongside roast meats."],"source":"user","provenance":"ai-draft"}},{"slug":"aussie-meat-pies","title":"Aussie Meat Pies","cuisine":"modern-australian","meal_types":["lunch","dinner"],"diets":["no-dairy"],"difficulty":"medium","total_minutes":120,"recipe":{"id":"aussie-meat-pies","title":"Aussie Meat Pies","summary":"Individual pies of rich beef mince gravy in flaky puff pastry, with tomato sauce on top.","cuisine":"modern-australian","diets":["no-dairy"],"mealTypes":["lunch","dinner"],"difficulty":"medium","prepMinutes":50,"cookMinutes":70,"servings":6,"onePot":false,"seasons":["autumn","winter"],"ingredientGroups":[{"title":"Filling","items":[{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"beef mince","raw":"750g beef mince","quantity":750,"unit":"g","ingredientId":"beef-mince"},{"item":"plain flour","raw":"2 tbsp plain flour","quantity":2,"unit":"tbsp","ingredientId":"plain-flour"},{"item":"tomato paste","raw":"2 tbsp tomato paste","quantity":2,"unit":"tbsp","ingredientId":"tomato-paste"},{"item":"tomato sauce","raw":"2 tbsp tomato sauce","quantity":2,"unit":"tbsp","ingredientId":"tomato-sauce"},{"item":"Worcestershire sauce","raw":"1 tbsp Worcestershire sauce","quantity":1,"unit":"tbsp","ingredientId":"worcestershire-sauce"},{"item":"beef stock","raw":"375ml beef stock","quantity":375,"unit":"ml","ingredientId":"beef-stock"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/2 tsp black pepper","quantity":0.5,"unit":"tsp","ingredientId":"black-pepper"}]},{"title":"Pastry","items":[{"item":"frozen puff pastry","raw":"4 sheets frozen puff pastry, just thawed","quantity":4,"unit":"sheet","ingredientId":"puff-pastry","prep":"just thawed"},{"item":"egg","raw":"1 egg, beaten, for brushing","quantity":1,"ingredientId":"egg","prep":"beaten, for brushing"}]},{"title":"To serve","items":[{"item":"Tomato sauce","raw":"Tomato sauce, to serve","ingredientId":"tomato-sauce","prep":"to serve"}]}],"steps":[{"text":"Heat the oil in a large saucepan over medium-high heat. Cook the onion for 5 minutes, then add the mince and cook for 8 minutes, breaking it up, until browned."},{"text":"Stir in the flour and tomato paste for 1 minute. Add the tomato sauce, Worcestershire, stock, salt and pepper. Simmer gently, stirring now and then, for 25 minutes, until thick enough to hold its shape. Spread on a tray to cool for 20 minutes, then refrigerate until cold."},{"text":"Heat the oven to 210°C (190°C fan-forced) with a tray inside. Grease a 6-hole Texas muffin tin (or six 10cm pie tins)."},{"text":"Cut six 14cm circles from the pastry for the bases and six 10cm circles for the lids, re-chilling the pastry if it goes soft. Press the bases into the tin and fill with the cold filling."},{"text":"Brush the pastry edges with egg, put the lids on and press to seal. Brush the tops with egg and cut a small slit in each."},{"text":"Set the tin on the hot tray and bake for 25 to 30 minutes, until puffed and deep golden and the filling is piping hot (75°C in the centre). Rest for 5 minutes, then lift out and serve with tomato sauce."}],"notes":["Cold filling stops the pastry going soggy. Make it the day before if you like; cover and refrigerate once cooled.","Cooked pies freeze well. Reheat from frozen at 180°C (160°C fan-forced) for 25 minutes, until piping hot.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"source":"user","provenance":"ai-draft"}},{"slug":"zucchini-slice","title":"Zucchini Slice","cuisine":"modern-australian","meal_types":["lunch","snack"],"diets":[],"difficulty":"easy","total_minutes":55,"recipe":{"id":"zucchini-slice","title":"Zucchini Slice","summary":"The lunchbox classic: grated zucchini, bacon and cheese baked into an easy, sliceable bake.","cuisine":"modern-australian","diets":[],"mealTypes":["lunch","snack"],"difficulty":"easy","prepMinutes":20,"cookMinutes":35,"servings":6,"onePot":true,"ingredientGroups":[{"items":[{"item":"zucchini","raw":"3 zucchini (about 450g), coarsely grated","quantity":3,"ingredientId":"zucchini","prep":"coarsely grated","note":"about 450g"},{"item":"brown onion","raw":"1 brown onion, finely diced","quantity":1,"ingredientId":"brown-onion","prep":"finely diced"},{"item":"bacon","raw":"200g bacon, diced","quantity":200,"unit":"g","ingredientId":"bacon","prep":"diced"},{"item":"tasty cheese","raw":"150g tasty cheese, grated","quantity":150,"unit":"g","ingredientId":"tasty-cheese","prep":"grated"},{"item":"self-raising flour","raw":"150g self-raising flour","quantity":150,"unit":"g","ingredientId":"self-raising-flour"},{"item":"eggs","raw":"5 eggs","quantity":5,"ingredientId":"egg"},{"item":"neutral oil","raw":"60ml neutral oil","quantity":60,"unit":"ml","ingredientId":"neutral-oil"},{"item":"salt","raw":"1/2 tsp salt","quantity":0.5,"unit":"tsp","ingredientId":"salt"},{"item":"black pepper","raw":"1/4 tsp black pepper","quantity":0.25,"unit":"tsp","ingredientId":"black-pepper"},{"item":"parsley","raw":"2 tbsp parsley, chopped","quantity":2,"unit":"tbsp","ingredientId":"parsley","prep":"chopped"}]}],"steps":[{"text":"Heat the oven to 180°C (160°C fan-forced). Grease and line a 20 x 30cm slice tin with baking paper."},{"text":"Squeeze the grated zucchini lightly in your hands to get rid of some of the water."},{"text":"In a large bowl, mix the zucchini, onion, bacon, cheese and flour."},{"text":"Whisk the eggs, oil, salt and pepper, pour into the bowl with the parsley and mix well. Spread evenly in the tin."},{"text":"Bake for 30 to 35 minutes, until golden and firm in the middle when pressed. Cool in the tin for 10 minutes before cutting into squares. Serve warm or cold."}],"notes":["For a vegetarian slice, leave out the bacon and add a grated carrot and a handful of corn kernels.","Keeps for 3 days in the fridge and freezes well in portions."],"source":"user","provenance":"ai-draft"}},{"slug":"sang-choy-bow","title":"Sang Choy Bow","cuisine":"modern-australian","meal_types":["dinner"],"diets":["no-dairy"],"difficulty":"easy","total_minutes":25,"recipe":{"id":"sang-choy-bow","title":"Sang Choy Bow","summary":"Quick stir-fried pork mince with water chestnuts and oyster sauce, eaten in cool iceberg lettuce cups.","cuisine":"modern-australian","diets":["no-dairy"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":10,"servings":4,"onePot":true,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Filling","items":[{"item":"neutral oil","raw":"1 tbsp neutral oil","quantity":1,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"garlic","raw":"2 garlic cloves, finely chopped","quantity":2,"unit":"clove","ingredientId":"garlic","prep":"finely chopped"},{"item":"ginger","raw":"1 tbsp ginger, finely grated","quantity":1,"unit":"tbsp","ingredientId":"ginger","prep":"finely grated"},{"item":"pork mince","raw":"500g pork mince","quantity":500,"unit":"g","ingredientId":"pork-mince"},{"item":"carrot","raw":"1 carrot, finely diced","quantity":1,"ingredientId":"carrot","prep":"finely diced"},{"item":"water chestnuts","raw":"225g tin water chestnuts, drained and chopped","quantity":225,"unit":"g","ingredientId":"water-chestnut","prep":"drained and chopped","note":"tin"},{"item":"oyster sauce","raw":"2 tbsp oyster sauce","quantity":2,"unit":"tbsp","ingredientId":"oyster-sauce"},{"item":"soy sauce","raw":"1 tbsp soy sauce","quantity":1,"unit":"tbsp","ingredientId":"soy-sauce"},{"item":"Shaoxing wine","raw":"1 tbsp Shaoxing wine","quantity":1,"unit":"tbsp","ingredientId":"shaoxing-wine"},{"item":"sesame oil","raw":"1 tsp sesame oil","quantity":1,"unit":"tsp","ingredientId":"sesame-oil"},{"item":"bean sprouts","raw":"100g bean sprouts","quantity":100,"unit":"g","ingredientId":"bean-sprouts"},{"item":"spring onions","raw":"4 spring onions, thinly sliced","quantity":4,"ingredientId":"spring-onion","prep":"thinly sliced"}]},{"title":"To serve","items":[{"item":"iceberg lettuce","raw":"1 iceberg lettuce, leaves separated into cups","quantity":1,"ingredientId":"iceberg-lettuce","prep":"leaves separated into cups"},{"item":"fried shallots","raw":"2 tbsp fried shallots","quantity":2,"unit":"tbsp","ingredientId":"fried-shallots"},{"item":"long red chilli","raw":"1 long red chilli, thinly sliced","quantity":1,"ingredientId":"red-chilli","prep":"thinly sliced"},{"item":"Hoisin sauce","raw":"Hoisin sauce, to serve","ingredientId":"hoisin-sauce","prep":"to serve"}]}],"steps":[{"text":"Trim the lettuce cups with scissors into neat bowls and keep them in iced water while you cook, then drain well."},{"text":"Heat the oil in a wok over high heat. Stir-fry the garlic and ginger for 30 seconds, then add the pork and stir-fry for 5 minutes, breaking it up, until browned and cooked through with no pink left."},{"text":"Add the carrot and water chestnuts and stir-fry for 1 minute. Add the oyster sauce, soy sauce, Shaoxing wine and sesame oil and toss for 1 minute."},{"text":"Take off the heat and toss through the bean sprouts and most of the spring onion."},{"text":"Spoon the filling into lettuce cups at the table, topped with fried shallots, chilli, the rest of the spring onion and a little hoisin."}],"notes":["Chicken mince works just as well.","Water chestnuts are what give it the crunch, so don't skip them.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"source":"user","provenance":"ai-draft"}},{"slug":"ricotta-hotcakes","title":"Ricotta Hotcakes","cuisine":"modern-australian","meal_types":["breakfast"],"diets":["vegetarian"],"difficulty":"easy","total_minutes":35,"recipe":{"id":"ricotta-hotcakes","title":"Ricotta Hotcakes","summary":"Tall, soft hotcakes made light with ricotta and whipped egg whites, served with maple syrup and berries.","cuisine":"modern-australian","diets":["vegetarian"],"mealTypes":["breakfast"],"difficulty":"easy","prepMinutes":15,"cookMinutes":20,"servings":4,"onePot":false,"ingredientGroups":[{"title":"Batter","items":[{"item":"fresh ricotta","raw":"300g fresh ricotta","quantity":300,"unit":"g","ingredientId":"ricotta"},{"item":"milk","raw":"180ml milk","quantity":180,"unit":"ml","ingredientId":"milk"},{"item":"eggs","raw":"4 eggs, separated","quantity":4,"ingredientId":"egg","prep":"separated"},{"item":"caster sugar","raw":"1 tbsp caster sugar","quantity":1,"unit":"tbsp","ingredientId":"caster-sugar"},{"item":"plain flour","raw":"150g plain flour","quantity":150,"unit":"g","ingredientId":"plain-flour"},{"item":"baking powder","raw":"1 tsp baking powder","quantity":1,"unit":"tsp","ingredientId":"baking-powder"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"},{"item":"butter","raw":"30g butter, for the pan","quantity":30,"unit":"g","ingredientId":"butter","prep":"for the pan"}]},{"title":"To serve","items":[{"item":"Maple syrup","raw":"Maple syrup","ingredientId":"maple-syrup"},{"item":"frozen mixed berries","raw":"150g frozen mixed berries, thawed","quantity":150,"unit":"g","ingredientId":"frozen-berries","prep":"thawed"},{"item":"Icing sugar","raw":"Icing sugar, for dusting","ingredientId":"icing-sugar","prep":"for dusting"}]}],"steps":[{"text":"Mix the ricotta, milk, egg yolks and sugar in a bowl. Sift in the flour and baking powder and stir until just combined."},{"text":"In a clean bowl, whisk the egg whites with the salt to stiff peaks. Fold them through the batter in two batches, keeping as much air as you can."},{"text":"Heat a large non-stick frying pan over medium-low heat and brush with a little butter. Drop in 1/4 cup of batter per hotcake, leaving room to spread."},{"text":"Cook for 2 to 3 minutes, until golden underneath and set around the edges. Flip carefully and cook for 2 minutes more, until golden and springy in the middle. Keep warm in a low oven while you cook the rest."},{"text":"Serve stacked, with maple syrup and berries, dusted with icing sugar."}],"notes":["Use fresh ricotta from the deli counter if you can. Tub ricotta is wetter; drain it in a sieve for 15 minutes first.","Sliced banana and a slice of honey butter is the cafe way to serve them."],"source":"user","provenance":"ai-draft"}},{"slug":"crispy-skin-barramundi","title":"Crispy-Skin Barramundi with Greens","cuisine":"modern-australian","meal_types":["dinner"],"diets":["pescatarian","no-gluten"],"difficulty":"easy","total_minutes":40,"recipe":{"id":"crispy-skin-barramundi","title":"Crispy-Skin Barramundi with Greens","summary":"Pan-fried barramundi with shatteringly crisp skin, spring greens, baby potatoes and a caper herb dressing.","cuisine":"modern-australian","diets":["pescatarian","no-gluten"],"mealTypes":["dinner"],"difficulty":"easy","prepMinutes":15,"cookMinutes":25,"servings":4,"onePot":false,"seasons":["spring","summer"],"ingredientGroups":[{"title":"Herb dressing","items":[{"item":"parsley","raw":"Handful of parsley, finely chopped","quantity":1,"unit":"handful","ingredientId":"parsley","prep":"finely chopped"},{"item":"capers","raw":"1 tbsp capers, rinsed and chopped","quantity":1,"unit":"tbsp","ingredientId":"capers","prep":"rinsed and chopped"},{"item":"Dijon mustard","raw":"1 tsp Dijon mustard","quantity":1,"unit":"tsp","ingredientId":"dijon-mustard"},{"item":"lemon","raw":"1 lemon, zested and juiced","quantity":1,"ingredientId":"lemon","prep":"zested and juiced"},{"item":"extra virgin olive oil","raw":"4 tbsp extra virgin olive oil","quantity":4,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"salt","raw":"Pinch of salt","quantity":1,"unit":"pinch","ingredientId":"salt"}]},{"title":"Potatoes and greens","items":[{"item":"baby potatoes","raw":"600g baby potatoes, halved","quantity":600,"unit":"g","ingredientId":"waxy-potato","prep":"halved"},{"item":"broccolini","raw":"2 bunches broccolini, trimmed","quantity":2,"unit":"bunch","ingredientId":"broccolini","prep":"trimmed"},{"item":"sugar snap peas","raw":"150g sugar snap peas, trimmed","quantity":150,"unit":"g","ingredientId":"sugar-snap-peas","prep":"trimmed"},{"item":"asparagus","raw":"1 bunch asparagus, trimmed","quantity":1,"unit":"bunch","ingredientId":"asparagus","prep":"trimmed"},{"item":"olive oil","raw":"1 tbsp olive oil","quantity":1,"unit":"tbsp","ingredientId":"olive-oil"},{"item":"garlic","raw":"1 garlic clove, thinly sliced","quantity":1,"unit":"clove","ingredientId":"garlic","prep":"thinly sliced"}]},{"title":"Fish","items":[{"item":"skin-on barramundi","raw":"4 skin-on barramundi fillets, about 180g each","quantity":4,"unit":"fillet","ingredientId":"white-fish","prep":"about 180g each"},{"item":"salt","raw":"1 tsp salt","quantity":1,"unit":"tsp","ingredientId":"salt"},{"item":"neutral oil","raw":"2 tbsp neutral oil","quantity":2,"unit":"tbsp","ingredientId":"neutral-oil"},{"item":"butter","raw":"20g butter","quantity":20,"unit":"g","ingredientId":"butter"}]}],"steps":[{"text":"Mix the dressing ingredients and set aside."},{"text":"Boil the potatoes in salted water for 15 minutes until tender. Add the broccolini, sugar snaps and asparagus for the last 2 minutes, then drain. Toss the greens and potatoes with the olive oil and garlic and keep warm."},{"text":"Meanwhile, pat the fish skin very dry with paper towel and score it two or three times. Season both sides with the salt."},{"text":"Heat the neutral oil in a large non-stick frying pan over medium-high heat. Lay the fillets in skin side down and press them flat with a spatula for the first 30 seconds so the skin doesn't curl. Cook without moving for 5 to 6 minutes, until the skin is deep golden and the flesh is opaque most of the way up."},{"text":"Flip, add the butter and cook for 1 minute more, until the fish is just opaque in the middle and flakes easily."},{"text":"Serve the fish skin side up on the potatoes and greens, with the dressing spooned around (not on the skin, which keeps it crisp)."}],"notes":["Dry skin is the whole trick. If you have time, leave the fillets uncovered on a plate in the fridge for an hour first.","Snapper or salmon fillets work the same way.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"source":"user","provenance":"ai-draft"}}]$q$::jsonb)), dn as (select r, row_number() over (partition by r->>'cuisine' order by r->>'slug') rn from d), cand as (select c.id, x.cuisine, row_number() over (partition by x.cuisine order by c.recipe_count, c.handle)-1 ix, count(*) over (partition by x.cuisine) cnt from public.cooks c join (select distinct cook_id, cuisine from public.published_recipes where status='published') x on x.cook_id=c.id where c.kind='person'), ins as (insert into public.published_recipes (cook_id,slug,title,cuisine,meal_types,diets,difficulty,total_minutes,recipe,review,status) select coalesce((select cd.id from cand cd where cd.cuisine=dn.r->>'cuisine' and cd.ix=(dn.rn-1)%cd.cnt),(select id from public.cooks where kind='official' limit 1)), dn.r->>'slug', dn.r->>'title', dn.r->>'cuisine', array(select jsonb_array_elements_text(dn.r->'meal_types')), array(select jsonb_array_elements_text(dn.r->'diets')), dn.r->>'difficulty', (dn.r->>'total_minutes')::int, jsonb_set(dn.r->'recipe','{notes}',coalesce((select jsonb_agg(n) from jsonb_array_elements(dn.r->'recipe'->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)), 'auto-checked','published' from dn where not exists (select 1 from public.published_recipes q where q.slug=dn.r->>'slug') on conflict do nothing returning id) select (select count(*) from d) expected, (select count(*) from ins) inserted;